/**
 * CHOOSING-1 — the frozen case set.
 *
 * Written 2026-08-31, before any run, against hause@b68d451. The
 * stimulus deliberately avoids HAUSE's own vocabulary: a case that says
 * "I want to make a claim that answers to evidence" is testing whether a
 * selector can read, not whether it can choose.
 *
 * Do not edit after publication. Failures here change the system; the
 * changed system is measured on CHOOSING-2, built from fresh material.
 */

export type Domain = "technical" | "editorial" | "commerce" | "operations" | "narrative" | "data" | "product";
export type Kind = "clear" | "trap" | "ambiguous" | "no-form";

export type Case = {
	id: string;
	/** What someone is trying to do, in their words — never HAUSE's. */
	content: string;
	/** The form the authority says fits. "NONE" where refusal is correct. */
	expected: string;
	/** Why — the deciding test, in this case's own terms. */
	decidingTest: string;
	/** The form most likely to be chosen instead. */
	nearestAlternative?: string;
	whyAlternativeLoses?: string;
	/** Ambiguous cases: other answers that are also correct. */
	alsoAcceptable?: string[];
	domain: Domain;
	kind: Kind;
};

